import{_ as t}from"./chunks/settings-sw.pc.ko.DMNWWZPp.js";import{_ as a,o as e,c as r,a5 as l}from"./chunks/framework.D47SInms.js";const u=JSON.parse('{"title":"이전 버전 되돌리기","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/version-rollback.md","filePath":"ko/manual/troubleshooting/version-rollback.md","lastUpdated":1791600043000}'),i={name:"ko/manual/troubleshooting/version-rollback.md"};function s(n,o,d,c,h,g){return e(),r("div",null,[...o[0]||(o[0]=[l('<h1 id="이전-버전-되돌리기" tabindex="-1">이전 버전 되돌리기 <a class="header-anchor" href="#이전-버전-되돌리기" aria-label="Permalink to &quot;이전 버전 되돌리기&quot;">​</a></h1><p>새 버전에서 문제가 생겨 이전 버전으로 돌아가야 하는 경우입니다. 되돌리기는 업데이트와 <strong>같은 화면에서 같은 방법으로</strong> 진행합니다 — 목록에서 낮은 버전을 고르면 되며, 별도의 제한은 없습니다.</p><h2 id="before" tabindex="-1">되돌리기 전에 <a class="header-anchor" href="#before" aria-label="Permalink to &quot;되돌리기 전에 {#before}&quot;">​</a></h2><ul><li>되돌릴 <strong>버전 번호</strong>를 미리 확인합니다.</li><li><strong>앱과 로봇은 서로 다른 대상</strong>입니다. 어느 쪽을 되돌릴 것인지 정하세요.</li><li>로봇을 되돌릴 때는 재부팅이 필요하므로 <strong>로봇을 앉힐 수 있는 장소</strong>에서 진행합니다.</li></ul><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>로봇 소프트웨어는 <strong>재부팅해야 적용됩니다.</strong> 재부팅하면 모터 전원이 끊겨 로봇이 주저앉습니다 — 먼저 <strong>앉힌 뒤</strong> 바닥에 앉아 있는지 확인하고, 재부팅이 끝날 때까지 로봇을 움직이지 마세요. 로봇이 서 있는 동안에는 재부팅 명령이 무시되며 <strong>앱에 오류가 나오지 않습니다.</strong></p></div></div><h2 id="rollback-robot" tabindex="-1">로봇을 이전 버전으로 되돌리기 <a class="header-anchor" href="#rollback-robot" aria-label="Permalink to &quot;로봇을 이전 버전으로 되돌리기 {#rollback-robot}&quot;">​</a></h2><p><img src="'+t+'" alt="정비 → 소프트웨어 업데이트"></p><ol><li>컨트롤러를 <strong>인터넷이 되는 Wi-Fi</strong>에 연결합니다. (로봇 Wi-Fi가 아닙니다.)</li><li><strong>정비 → 소프트웨어 업데이트</strong>를 엽니다.</li><li><code>버전 확인</code>으로 목록을 받아온 뒤, 되돌릴 <strong>이전 버전</strong>의 <code>다운로드</code>를 누릅니다. 받은 파일은 기기에 남습니다.</li><li>컨트롤러를 <strong>로봇 Wi-Fi</strong>(<code>RBQ_</code>로 시작하는 이름)로 다시 연결합니다.</li><li><code>업데이트 파일</code> 카드에 되돌릴 버전이 들어 있는지, <code>대상</code>이 <code>Motion</code>인지 확인합니다.</li><li><code>로봇 소프트웨어 전송</code> → 확인 대화상자에서 <code>전송</code>을 누릅니다.</li><li>전송이 끝나면 재부팅을 묻습니다. <strong>로봇을 앉힌 뒤</strong> <code>지금 재부팅</code>을 누릅니다.</li><li>다시 연결한 뒤 <code>현재 로봇</code> 카드의 <code>버전</code>이 되돌린 버전인지 확인합니다.</li></ol><p>화면 각 항목의 자세한 설명은 <a href="/RBQ/nightly/ko/manual/gui/software-update.html">소프트웨어 업데이트</a>에 있습니다.</p><h2 id="rollback-app" tabindex="-1">앱을 이전 버전으로 되돌리기 <a class="header-anchor" href="#rollback-app" aria-label="Permalink to &quot;앱을 이전 버전으로 되돌리기 {#rollback-app}&quot;">​</a></h2><p>되돌리는 방법은 앱을 어떻게 설치했느냐에 따라 다릅니다.</p><table tabindex="0"><thead><tr><th>설치 경로</th><th>되돌리는 법</th></tr></thead><tbody><tr><td><strong>데스크탑 · Steam Deck</strong></td><td>같은 화면에서 되돌릴 버전을 <code>다운로드</code>한 뒤, 그 줄의 <code>앱 설치</code>로 전환합니다</td></tr><tr><td><strong>Android (APK 직접 설치)</strong></td><td><a href="/RBQ/nightly/ko/manual/downloads/">다운로드</a>에서 이전 버전 APK를 받아 설치합니다</td></tr><tr><td><strong>Google Play · App Store</strong></td><td><strong>스토어는 이전 버전 설치를 지원하지 않습니다.</strong> 되돌려야 한다면 위 직접 설치본을 쓰세요</td></tr></tbody></table><p><code>GUI Version</code> 줄의 배지로 지금 어떤 빌드인지 알 수 있습니다 — 배지 없음은 정식, <code>NIGHTLY</code>는 나이틀리, <code>LOCAL</code>은 배포 채널이 없는 로컬 빌드입니다. <strong>나이틀리 빌드는 최근 10일치만 남으므로 그보다 오래된 나이틀리로는 되돌릴 수 없습니다</strong> — 정식 버전을 고르세요.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>버전을 받을 때는 <strong>인터넷</strong>이, 로봇에 전송할 때는 <strong>로봇 Wi-Fi</strong>가 필요합니다. 되돌릴 버전을 먼저 받아 두고 로봇 Wi-Fi로 바꾸는 순서로 진행하세요.</p></div></div><h2 id="offline" tabindex="-1">인터넷이 없는 환경에서 되돌리기 <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;인터넷이 없는 환경에서 되돌리기 {#offline}&quot;">​</a></h2><p>폐쇄망처럼 인터넷을 쓸 수 없는 환경에서는 파일로 되돌립니다.</p><ol><li>인터넷이 되는 곳에서 되돌릴 버전의 <code>RBQ-&lt;version&gt;.tar.gz</code>를 미리 받아 USB에 담습니다.</li><li>소프트웨어 업데이트 화면에서 <code>USB·파일에서 불러오기</code>를 누르고 그 파일을 고릅니다.</li><li>이후는 위 <a href="#rollback-robot">로봇 되돌리기</a>의 5번부터와 같습니다.</li></ol><p>파일 이름은 반드시 <code>RBQ-&lt;version&gt;.tar.gz</code> 형식이어야 합니다 — 다른 이름은 로봇이 거부합니다.</p><h2 id="after" tabindex="-1">되돌린 뒤 확인할 것 <a class="header-anchor" href="#after" aria-label="Permalink to &quot;되돌린 뒤 확인할 것 {#after}&quot;">​</a></h2><ul><li><code>현재 로봇</code> 카드의 버전과 <code>GUI Version</code>이 의도한 버전인지 확인합니다.</li><li>로봇을 일으켜 <a href="/RBQ/nightly/ko/manual/gui/motion-commands.html">기본 동작</a>이 정상인지 확인합니다.</li><li>카메라 영상이 나오지 않으면 <a href="/RBQ/nightly/ko/manual/troubleshooting/no-camera-view.html">카메라 영상이 나오지 않을 때</a>를 확인하세요.</li></ul><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>되돌리기 전 버전과 되돌린 버전, 그리고 되돌리게 된 증상을 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/nightly/ko/manual/support/">기술지원 요청</a></strong></p>',23)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
